from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class FHLicensedv1HttpClient(HttpClient):
    """ This class provides a client for the FH Licensed v1 API. """

    def __init__(self, base_url, connection_alias):
        super(FHLicensedv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def get_real_time_measurements(self, rmods_runtime_distnames=None, start_time=None, timeout=30):
        endpoint = '/real-time-measurements'
        payload = {
            "targetDN": rmods_runtime_distnames,
            "startTimeLowerLimit": start_time
        }
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, payload=payload, timeout=timeout, headers=headers)

    def get_rmod_measurements_by_id(self, rmod_id, limit_to=None, timeout=60):
        endpoint = f'/rmods/measurements/{rmod_id}'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }

        payload = {
            "filter": limit_to
        }

        return self._send_get_request(endpoint=endpoint, payload=payload, timeout=timeout, headers=headers)

    def reset_rmods(self, rmods_list, reset_reason, graceful_cell_shutdown, timeout):
        endpoint = '/rmods/operations/resets'
        headers = {
            "Content-Type": "application/json",
        }

        payload = {
            "ids": rmods_list,
            "resetReason": reset_reason,
            "gracefulCellShutdown": "true" if graceful_cell_shutdown else "false"
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def get_status_of_reset_rmods(self, operation_id, timeout=30):
        endpoint = f'/rmods/operations/resets/{operation_id}'
        return self._send_get_request(endpoint=endpoint, timeout=timeout)

    def start_antenna_monitoring(self, antennas, timeout=30):
        endpoint = '/diagnostic/rf-antenna-monitors'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=antennas)

    def get_antenna_monitoring_status(self, monitor_id, timeout=30):
        endpoint = f'/diagnostic/rf-antenna-monitors/{monitor_id}'
        return self._send_get_request(endpoint=endpoint, timeout=timeout)

    def stop_antenna_monitoring(self, monitor_id, timeout=30):
        endpoint = f'/diagnostic/rf-antenna-monitors/{monitor_id}'
        headers = {
            "Content-Type": "application/json",
        }

        self._send_delete_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_antenna_monitoring_results(self, monitor_id, timeout=30):
        endpoint = f'/diagnostic/rf-antenna-monitors/{monitor_id}/results'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_antenna_monitoring_result_file(self, directory, timeout=30):
        endpoint = '/diagnostic/rf-antenna-monitors/result-file'
        headers = {
            "accept": "application/x-gzip-compressed"
        }
        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout, return_response_headers=True)

    def start_rf_scan_test(self, ru_dn, signal, antenna=None, antenna_carrier=None, antenna_panel=None, timeout=30):
        endpoint = '/diagnostic/rf-scan-test'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }
        payload = {
            "ruDN": ru_dn,
            "signal": signal,
        }
        if antenna is not None:
            payload["antenna"] = antenna
        if antenna_carrier is not None:
            payload["antennaCarrier"] = antenna_carrier
        if antenna_panel is not None:
            payload["antennaPanel"] = antenna_panel

        return self._send_post_request(endpoint=endpoint, headers=headers, json=payload, timeout=timeout)

    def get_rf_scan_test_operation_status(self, operation_id, timeout=30):
        endpoint = f'/diagnostic/rf-scan-test/{operation_id}'
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_rf_scan_test_operation(self, operation_id, timeout=30):
        endpoint = f'/diagnostic/rf-scan-test/{operation_id}'
        headers = {
            "accept": "*/*",
        }

        return self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def cancel_rf_scan_test_operation(self, timeout=30):
        endpoint = '/diagnostic/rf-scan-test/cancel'
        headers = {
            "accept": "application/json",
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_rf_scan_test_cancellation_status(self, operation_id, timeout=30):
        endpoint = f'/diagnostic/rf-scan-test/cancel/{operation_id}'
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_rf_scan_test_cancel_operation(self, operation_id, timeout=30):
        endpoint = f'/diagnostic/rf-scan-test/cancel/{operation_id}'
        headers = {
            "accept": "*/*",
        }

        return self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_rf_scan_test_file(self, timeout=30):
        endpoint = '/diagnostic/rf-scan-test/result-file'
        headers = {
            "accept": "application/octet-stream"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout, return_response_headers=False)

    def set_ret_configuration(self, target_dn="", timeout=30, **kwargs):
        endpoint = '/alds/rets/operations/common-configuration'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }

        set_ret_configuration_data_item = {
            "targetDN": target_dn,
            "retUAliasLabel": kwargs.get('alias_label', ""),
            "deviceData": kwargs.get('device_data', ""),
            "antennaBearing": kwargs.get('antenna_bearing', ""),
            "maxAngle": kwargs.get('max_angle', ""),
            "mechanicalAngle": kwargs.get('mechanical_angle', ""),
            "minAngle": kwargs.get('min_angle', ""),
            "angle": kwargs.get('angle', ""),
            "calibration": kwargs.get('calibration', "false")
            }

        antenna_info_input = kwargs.get('antenna_info')
        if antenna_info_input:
            antenna_info = {
                "antennaModelNumber": antenna_info_input.get('model_number', ""),
                "antennaSerialNumber": antenna_info_input.get('serial_number', ""),
                "installationDate": antenna_info_input.get('installation_date', ""),
                "installerId": antenna_info_input.get('installer_id', ""),
                "baseStationId": antenna_info_input.get('base_station_id', ""),
                "sectorId": antenna_info_input.get('sector_id', "")
            }

            set_ret_configuration_data_item["antennaInfo"] = antenna_info

        return self._send_patch_request(endpoint=endpoint,
                                        headers=headers,
                                        payload=[set_ret_configuration_data_item],
                                        timeout=timeout)

    def get_ald_reset_status(self, operation_id, timeout=30):
        endpoint = f'/alds/operations/reset/{operation_id}'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_ald_select_mode_operation_status(self, operation_id, timeout=30):
        endpoint = f'/alds/selection-mode/{operation_id}'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_alds_selection_mode(self, timeout=30):
        endpoint = '/alds/selection-mode'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def trigger_ald_selection_mode(self, ald_selection_mode, timeout=30):
        endpoint = '/alds/selection-mode'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }
        payload = {
            "aldSelectionMode": ald_selection_mode
        }
        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def create_ald_reset(self, target_dn, type, timeout=30):
        endpoint = '/alds/operations/reset'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }
        payload = {
            "type": type,
            "targetDN": target_dn
        }
        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def start_diagnostic_rf_statistics_diagnostic_test(self, target_rmod_id=-1, act_remote_rf_diag=True, high_threshold=80,
                                                       low_threshold=-5, timeout=60):
        endpoint = '/diagnostic/rf-statistics-diagnostic-test'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }

        json_data = {
            'targetRmodId': target_rmod_id,
            'actRemoteRfDiag': act_remote_rf_diag,
            'thresholds': {
                'rfTemperatureHighThreshold': high_threshold,
                'rfTemperatureLowThreshold': low_threshold,
            },
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=json_data, timeout=timeout)

    def get_diagnostic_rf_statistics_diagnostic_test_status(self, operation_id, timeout=60):
        endpoint = f'/diagnostic/rf-statistics-diagnostic-test/{operation_id}'
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_diagnostic_rf_statistics_diagnostic_test_results(self, timeout=60):
        endpoint = '/diagnostic/rf-statistics-diagnostic-test/results'
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
